// ============ 优先级表 ============
//
//   运算符  优先级      说明
//   ──────  ────────   ──────────────────────
//     +        1       同级，从左往右算
//     -        1
//     *        2       同级，比加减高
//     /        2
//     (        0       栈内的左括号：优先级最低，谁来了都不弹它
//
// 为什么左括号在栈内要算 0？
//
// 因为左括号一旦入栈，就必须等到**遇到右括号**才能弹出。
// 把它的优先级设成最低，任何运算符来比较时都会觉得"它比我低，
// 不用弹"—— 正好实现了"括号内先算完再说"。
//
// 这是个小技巧，但很关键：如果左括号优先级设高了，
// 它会被后面的运算符弹出去，括号就白写了。

// 返回运算符 c 的优先级；不是运算符就返回 -1
// 返回 -1 是给调用者一个"这不是运算符"的信号，
// 顺便也覆盖了"右括号不该出现在这个比较里"的情况。
int priority(char c)
{
    switch (c)
    {
    case '+':
    case '-':
// 加减同级，最低
        return 1;
    case '*':
    case '/':
// 乘除同级，比加减高
        return 2;
    case '(':
// 栈内的左括号：最低，保证不会被提前弹出
        return 0;
    default:
// 不是运算符（包括右括号、操作数）
        return -1;
    }
}

