// ============ 四条规则 ============
//
//   遇到 操作数 （0-9）  →  直接输出
//   遇到 左括号          →  入栈
//   遇到 右括号          →  弹出并输出，直到遇上左括号（左括号弹出但不输出）
//   遇到 运算符          →  弹出并输出所有"优先级 >= 自己"的栈顶运算符，然后自己入栈
//   扫完之后             →  把栈里剩下的运算符全部弹出输出
//
// ============ 走一遍 "3+4*2" ============
//
//   输入    栈（底→顶）   输出
//   ─────  ───────────  ──────────
//    3       空           3          操作数，直接输出
//    +       +            3          栈空，直接入栈
//    4       +            34         操作数
//    *       + *          34         '*' 比栈顶 '+' 优先级**高**，不弹，入栈
//    2       + *          342        操作数
//   结束     空           342*+      剩余的依次弹出
//
// 注意第 4 步：如果来的是 '+'（而不是 '*'），那栈顶的 '+' 优先级**不低于**它，
// 就得先弹出输出 —— 这就是"同级从左往右算"的由来。
//
// 再看一个带括号的 "3*(4+2)"：
//
//   输入    栈          输出        说明
//   ─────  ─────────  ─────────  ──────────────────
//    3       空          3
//    *       *           3         '*' 比空栈，入
//    (       * (         3         左括号无条件入栈
//    4       * (         34
//    +       * ( +       34        '(' 优先级 0，不弹
//    2       * ( +       342
//    )       *           342+      弹到 '(' 为止，'(' 弹出但不输出
//   结束     空          342+*     弹出剩余的 '*'
//
// 结果 "342+*" 读回来就是 3*(4+2)=18 —— 括号消失了，
// 但运算顺序被完整地"编码"进了后缀式里。

// 把中缀表达式 src 转成后缀，写进 dst
// 返回值是后缀串的长度，方便调用者直接当字符串用
int InfixToPostfix(const char *src, char *dst)
{
// 运算符栈：只存运算符，容量给够就行
    char stack[64];
// 栈顶下标，-1 表示空栈（和 02-03 的约定保持一致）
    int top = -1;
// 输出位置
    int k = 0;
// 扫描下标
    int i;

// 从左往右扫一遍
    for (i = 0; src[i] != '\0'; i++)
    {
        char c = src[i];

// ① 操作数：直接输出，不进栈
        if (c >= '0' && c <= '9')
        {
            dst[k++] = c;
            continue;
        }

// ② 左括号：无条件入栈，它在等它的右括号
        if (c == '(')
        {
            stack[++top] = c;
            continue;
        }

// ③ 右括号：把括号里的运算符全部弹出输出
        if (c == ')')
        {
// 一直弹到左括号为止。左括号本身弹出后**不输出** ——
// 后缀式里没有括号的位置。
            while (top >= 0 && stack[top] != '(')
            {
                dst[k++] = stack[--top];
            }
// 把左括号也弹掉（不输出）
            if (top >= 0)
            {
                top--;
            }
            continue;
        }

// ④ 运算符：先让"优先级不低于自己"的栈顶元素出去
// 这里用的是 >= 而不是 >，这一条决定了同级运算"从左往右"。
// 如果写成 >，那么 "3-4+5" 会算成 3-(4+5)，结果就错了。
        while (top >= 0 && priority(stack[top]) >= priority(c))
        {
            dst[k++] = stack[--top];
        }
// 自己再入栈
        stack[++top] = c;
    }

// ⑤ 扫完了，把栈里剩下的全弹出来
    while (top >= 0)
    {
        dst[k++] = stack[--top];
    }

// 收尾：补字符串结束符
    dst[k] = '\0';

// 返回长度
    return k;
}

