// ============ 规则只有一条 ============
//
//   遇到 操作数  →  入栈
//   遇到 运算符  →  弹出两个数，算完把结果压回去
//   扫完之后     →  栈里只剩一个数，那就是答案
//
// 没有括号、没有优先级 —— 后缀式已经把运算顺序编码好了。
//
// ============ 走一遍 "342*+" ============
//
//   输入   栈（底→顶）    说明
//   ─────  ───────────  ──────────────────────
//    3      [3]          操作数入栈
//    4      [3, 4]       操作数入栈
//    2      [3, 4, 2]    操作数入栈
//    *      [3, 8]       弹出 4 和 2 → 4*2=8，压回
//    +      [11]         弹出 3 和 8 → 3+8=11，压回
//   结束    [11]         答案就是 11
//
// ============ 顺序陷阱：谁减谁 ============
//
// 弹出两个数时，**先弹出的是右操作数**！
//
//   "34-" 表示 3-4，扫描到 '-' 时：
//      第一次弹出的是 4（右操作数）
//      第二次弹出的是 3（左操作数）
//      所以计算应该是 b - a，而不是 a - b
//
// 加法和乘法无所谓（可交换），但减法和除法写反了结果就完全错。
// 这是后缀求值最经典的坑。

// 计算后缀表达式的值；出错返回 0 并把 ok 置 0
int EvalPostfix(const char *src, int *ok)
{
// 操作数栈：存的是数值，不是字符
    int stack[64];
// 栈顶下标
    int top = -1;
// 扫描下标
    int i;

// 先假设一切正常
    *ok = 1;

    for (i = 0; src[i] != '\0'; i++)
    {
        char c = src[i];

// ① 操作数：字符转数字后入栈
// c - '0' 就是字符到数字的转换：'3' 的 ASCII 是 51，减去 '0'(48) 得 3。
        if (c >= '0' && c <= '9')
        {
            stack[++top] = c - '0';
            continue;
        }

// ② 运算符：需要两个操作数
        if (top < 1)
        {
// 栈里不足两个数，说明表达式本身有问题（比如 "3+"）。
// 后缀式虽然好算，但**合法性检查还是得自己做**。
            *ok = 0;
            return 0;
        }

        {
// 先弹出的是右操作数
            int b = stack[top--];
// 后弹出的是左操作数
            int a = stack[top--];
// 结果
            int r = 0;

// 按运算符计算 —— 注意减法和除法的顺序
            switch (c)
            {
            case '+':
                r = a + b;
                break;
            case '-':
// 是 a - b（左减右），不是 b - a。写反了 "7 3 -"（=4）会算成 -4。
                r = a - b;
                break;
            case '*':
                r = a * b;
                break;
            case '/':
// 除数不能为 0，这里必须挡住，否则程序直接崩。
                if (b == 0)
                {
                    *ok = 0;
                    return 0;
                }
                r = a / b;
                break;
            default:
// 后缀式里不该出现别的字符（包括括号）
                *ok = 0;
                return 0;
            }

// 结果压回栈里，继续参与后面的运算
            stack[++top] = r;
        }
    }

// 扫完之后，栈里应该**正好剩一个数**
    if (top != 0)
    {
// 多了说明有多余操作数，空了说明表达式不完整 —— 都算失败。
        *ok = 0;
        return 0;
    }

// 栈顶就是答案
    return stack[0];
}

