// ============ 这两个算法是同一个思想的两次应用 ============
//
// 它们都靠一个栈，都在回答同一个问题：**"什么时候可以结算"**。
//
//   转后缀时：新来的运算符优先级不高于栈顶 → 栈顶那个可以先结算了
//   求值时  ：遇到运算符 → 前面攒够两个操作数了，可以结算了
//
// 把"迟到的计算"先存起来，等条件成熟再处理 —— 这个思路后面还会反复出现
// （递归、DFS、表达式树都是它）。

// 测试若干表达式，逐个对比
static void Try(const char *expr, const char *expectNote)
{
    char postfix[64];
    int ok = 0;
    int v;

    InfixToPostfix(expr, postfix);
    v = EvalPostfix(postfix, &ok);

    if (ok)
    {
        printf("%-12s -> 后缀 %-12s = %d\t%s\n", expr, postfix, v, expectNote);
