#include <stdio.h>

// ============ 优先级表 ============
//
//   运算符  优先级      说明
//   ──────  ────────   ──────────────────────
//     +        1       同级，从左往右算
//     -        1
//     *        2       同级，比加减高
//     /        2
//     (        0       栈内的左括号：优先级最低，谁来了都不弹它
//
// 为什么左括号在栈内要算 0？
//
// 因为左括号一旦入栈，就必须等到**遇到右括号**才能弹出。
// 把它的优先级设成最低，任何运算符来比较时都会觉得"它比我低，
// 不用弹"—— 正好实现了"括号内先算完再说"。
//
// 这是个小技巧，但很关键：如果左括号优先级设高了，
// 它会被后面的运算符弹出去，括号就白写了。

// 返回运算符 c 的优先级；不是运算符就返回 -1
// 返回 -1 是给调用者一个"这不是运算符"的信号，
// 顺便也覆盖了"右括号不该出现在这个比较里"的情况。
int priority(char c)
{
    switch (c)
    {
    case '+':
    case '-':
// 加减同级，最低
        return 1;
    case '*':
    case '/':
// 乘除同级，比加减高
        return 2;
    case '(':
// 栈内的左括号：最低，保证不会被提前弹出
        return 0;
    default:
// 不是运算符（包括右括号、操作数）
        return -1;
    }
}

// ============ 四条规则 ============
//
//   遇到 操作数 （0-9）  →  直接输出
//   遇到 左括号          →  入栈
//   遇到 右括号          →  弹出并输出，直到遇上左括号（左括号弹出但不输出）
//   遇到 运算符          →  弹出并输出所有"优先级 >= 自己"的栈顶运算符，然后自己入栈
//   扫完之后             →  把栈里剩下的运算符全部弹出输出
//
// ============ 走一遍 "3+4*2" ============
//
//   输入    栈（底→顶）   输出
//   ─────  ───────────  ──────────
//    3       空           3          操作数，直接输出
//    +       +            3          栈空，直接入栈
//    4       +            34         操作数
//    *       + *          34         '*' 比栈顶 '+' 优先级**高**，不弹，入栈
//    2       + *          342        操作数
//   结束     空           342*+      剩余的依次弹出
//
// 注意第 4 步：如果来的是 '+'（而不是 '*'），那栈顶的 '+' 优先级**不低于**它，
// 就得先弹出输出 —— 这就是"同级从左往右算"的由来。
//
// 再看一个带括号的 "3*(4+2)"：
//
//   输入    栈          输出        说明
//   ─────  ─────────  ─────────  ──────────────────
//    3       空          3
//    *       *           3         '*' 比空栈，入
//    (       * (         3         左括号无条件入栈
//    4       * (         34
//    +       * ( +       34        '(' 优先级 0，不弹
//    2       * ( +       342
//    )       *           342+      弹到 '(' 为止，'(' 弹出但不输出
//   结束     空          342+*     弹出剩余的 '*'
//
// 结果 "342+*" 读回来就是 3*(4+2)=18 —— 括号消失了，
// 但运算顺序被完整地"编码"进了后缀式里。

// 把中缀表达式 src 转成后缀，写进 dst
// 返回值是后缀串的长度，方便调用者直接当字符串用
int InfixToPostfix(const char *src, char *dst)
{
// 运算符栈：只存运算符，容量给够就行
    char stack[64];
// 栈顶下标，-1 表示空栈（和 02-03 的约定保持一致）
    int top = -1;
// 输出位置
    int k = 0;
// 扫描下标
    int i;

// 从左往右扫一遍
    for (i = 0; src[i] != '\0'; i++)
    {
        char c = src[i];

// ① 操作数：直接输出，不进栈
        if (c >= '0' && c <= '9')
        {
            dst[k++] = c;
            continue;
        }

// ② 左括号：无条件入栈，它在等它的右括号
        if (c == '(')
        {
            stack[++top] = c;
            continue;
        }

// ③ 右括号：把括号里的运算符全部弹出输出
        if (c == ')')
        {
// 一直弹到左括号为止。左括号本身弹出后**不输出** ——
// 后缀式里没有括号的位置。
            while (top >= 0 && stack[top] != '(')
            {
                dst[k++] = stack[--top];
            }
// 把左括号也弹掉（不输出）
            if (top >= 0)
            {
                top--;
            }
            continue;
        }

// ④ 运算符：先让"优先级不低于自己"的栈顶元素出去
// 这里用的是 >= 而不是 >，这一条决定了同级运算"从左往右"。
// 如果写成 >，那么 "3-4+5" 会算成 3-(4+5)，结果就错了。
        while (top >= 0 && priority(stack[top]) >= priority(c))
        {
            dst[k++] = stack[--top];
        }
// 自己再入栈
        stack[++top] = c;
    }

// ⑤ 扫完了，把栈里剩下的全弹出来
    while (top >= 0)
    {
        dst[k++] = stack[--top];
    }

// 收尾：补字符串结束符
    dst[k] = '\0';

// 返回长度
    return k;
}

// ============ 规则只有一条 ============
//
//   遇到 操作数  →  入栈
//   遇到 运算符  →  弹出两个数，算完把结果压回去
//   扫完之后     →  栈里只剩一个数，那就是答案
//
// 没有括号、没有优先级 —— 后缀式已经把运算顺序编码好了。
//
// ============ 走一遍 "342*+" ============
//
//   输入   栈（底→顶）    说明
//   ─────  ───────────  ──────────────────────
//    3      [3]          操作数入栈
//    4      [3, 4]       操作数入栈
//    2      [3, 4, 2]    操作数入栈
//    *      [3, 8]       弹出 4 和 2 → 4*2=8，压回
//    +      [11]         弹出 3 和 8 → 3+8=11，压回
//   结束    [11]         答案就是 11
//
// ============ 顺序陷阱：谁减谁 ============
//
// 弹出两个数时，**先弹出的是右操作数**！
//
//   "34-" 表示 3-4，扫描到 '-' 时：
//      第一次弹出的是 4（右操作数）
//      第二次弹出的是 3（左操作数）
//      所以计算应该是 b - a，而不是 a - b
//
// 加法和乘法无所谓（可交换），但减法和除法写反了结果就完全错。
// 这是后缀求值最经典的坑。

// 计算后缀表达式的值；出错返回 0 并把 ok 置 0
int EvalPostfix(const char *src, int *ok)
{
// 操作数栈：存的是数值，不是字符
    int stack[64];
// 栈顶下标
    int top = -1;
// 扫描下标
    int i;

// 先假设一切正常
    *ok = 1;

    for (i = 0; src[i] != '\0'; i++)
    {
        char c = src[i];

// ① 操作数：字符转数字后入栈
// c - '0' 就是字符到数字的转换：'3' 的 ASCII 是 51，减去 '0'(48) 得 3。
        if (c >= '0' && c <= '9')
        {
            stack[++top] = c - '0';
            continue;
        }

// ② 运算符：需要两个操作数
        if (top < 1)
        {
// 栈里不足两个数，说明表达式本身有问题（比如 "3+"）。
// 后缀式虽然好算，但**合法性检查还是得自己做**。
            *ok = 0;
            return 0;
        }

        {
// 先弹出的是右操作数
            int b = stack[top--];
// 后弹出的是左操作数
            int a = stack[top--];
// 结果
            int r = 0;

// 按运算符计算 —— 注意减法和除法的顺序
            switch (c)
            {
            case '+':
                r = a + b;
                break;
            case '-':
// 是 a - b（左减右），不是 b - a。写反了 "7 3 -"（=4）会算成 -4。
                r = a - b;
                break;
            case '*':
                r = a * b;
                break;
            case '/':
// 除数不能为 0，这里必须挡住，否则程序直接崩。
                if (b == 0)
                {
                    *ok = 0;
                    return 0;
                }
                r = a / b;
                break;
            default:
// 后缀式里不该出现别的字符（包括括号）
                *ok = 0;
                return 0;
            }

// 结果压回栈里，继续参与后面的运算
            stack[++top] = r;
        }
    }

// 扫完之后，栈里应该**正好剩一个数**
    if (top != 0)
    {
// 多了说明有多余操作数，空了说明表达式不完整 —— 都算失败。
        *ok = 0;
        return 0;
    }

// 栈顶就是答案
    return stack[0];
}

