    printf("\n=== 减法与除法（验证左右操作数顺序）===\n");
    Try("7-3", "应该是 4，不是 -4");
    Try("8/2", "应该是 4，不是 0");
    Try("8/2/2", "同级从左往右，= 2");

// 第四组：非法输入
