                top--;
            }
            continue;
        }

// ④ 运算符：先让"优先级不低于自己"的栈顶元素出去
        while (top >= 0 && priority(stack[top]) >= priority(c))
        {
            dst[k++] = stack[--top];
        }
// 自己再入栈
        stack[++top] = c;
    }

// ⑤ 扫完了，把栈里剩下的全弹出来
    while (top >= 0)
    {
        dst[k++] = stack[--top];
    }

// 收尾：补字符串结束符
    dst[k] = '\0';

// 返回长度
    return k;
}


// 计算后缀表达式的值；出错返回 0 并把 ok 置 0
int EvalPostfix(const char *src, int *ok)
{
// 操作数栈：存的是数值，不是字符
    int stack[64];
// 栈顶下标
    int top = -1;
// 扫描下标
    int i;

// 先假设一切正常
    *ok = 1;

    for (i = 0; src[i] != '\0'; i++)
    {
        char c = src[i];

// ① 操作数：字符转数字后入栈
        if (c >= '0' && c <= '9')
        {
            stack[++top] = c - '0';
            continue;
        }

// ② 运算符：需要两个操作数
        if (top < 1)
        {
            *ok = 0;
            return 0;
        }

        {
// 先弹出的是右操作数
            int b = stack[top--];
// 后弹出的是左操作数
            int a = stack[top--];
// 结果
            int r = 0;

// 按运算符计算 —— 注意减法和除法的顺序
            switch (c)
            {
            case '+':
                r = a + b;
                break;
            case '-':
                r = a - b;
                break;
            case '*':
                r = a * b;
                break;
            case '/':
                if (b == 0)
                {
                    *ok = 0;
                    return 0;
                }
                r = a / b;
                break;
            default:
                *ok = 0;
                return 0;
            }

// 结果压回栈里，继续参与后面的运算
            stack[++top] = r;
        }
    }

// 扫完之后，栈里应该**正好剩一个数**
    if (top != 0)
    {
        *ok = 0;
        return 0;
    }

// 栈顶就是答案
    return stack[0];
}


// 测试若干表达式，逐个对比
static void Try(const char *expr, const char *expectNote)
{
    char postfix[64];
    int ok = 0;
    int v;

    InfixToPostfix(expr, postfix);
    v = EvalPostfix(postfix, &ok);

    if (ok)
    {
        printf("%-12s -> 后缀 %-12s = %d\t%s\n", expr, postfix, v, expectNote);
    }
    else
    {
        printf("%-12s -> 后缀 %-12s = 表达式有误\t%s\n", expr, postfix, expectNote);
    }
}

// 主函数
int main(void)
{
// 第一组：验证优先级
    printf("=== 优先级 ===\n");
    Try("3+4*2", "先乘后加，= 11");
    Try("3*4+2", "先乘后加，= 14");
    Try("3+4-2", "同级从左往右，= 5");

// 第二组：验证括号
    printf("\n=== 括号 ===\n");
    Try("3*(4+2)", "括号优先，= 18");
    Try("(3+4)*2", "括号优先，= 14");
    Try("(1+2)*(3+4)", "两个括号，= 21");

// 第三组：验证减法顺序（最容易写错的地方）
    printf("\n=== 减法与除法（验证左右操作数顺序）===\n");
    Try("7-3", "应该是 4，不是 -4");
    Try("8/2", "应该是 4，不是 0");
    Try("8/2/2", "同级从左往右，= 2");

// 第四组：非法输入
    printf("\n=== 非法输入 ===\n");
    Try("3+", "操作数不够");
    Try("3 4", "空格不是操作数");
    Try("3/0", "除数为 0");

// 正常结束
    return 0;
}

